using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Web.Script.Serialization;
internal static class GuardBootstrapTests {
 static int checks;static JavaScriptSerializer json=new JavaScriptSerializer();static void Need(bool ok,string text){checks++;if(!ok)throw new Exception(text);}
 static bool Until(Func<bool> condition){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<3000){if(condition())return true;Thread.Sleep(20);}return condition();}
 static int Main(string[] args){string root=args[0],state=args[1],package=args[2],report=args[3];try{Directory.CreateDirectory(state);string manager=Path.Combine(root,"CodexLiveBackground.exe"),guard=Path.Combine(root,@"startup\DreamSkinPortHook.exe"),manifest=Path.Combine(root,"manifest.json");File.Copy(Path.Combine(package,"CodexLiveBackground.exe"),manager);File.Copy(Path.Combine(package,"service-compatibility.json"),Path.Combine(root,"service-compatibility.json"));File.WriteAllText(manifest,json.Serialize(new{version="1.7.0.9",files=new[]{new{path="CodexLiveBackground.exe",bytes=new FileInfo(manager).Length,sha256=SoftwareUpdate.Hash(manager)}}}));File.WriteAllText(Path.Combine(root,".codex-background-install.json"),json.Serialize(new{productId="codex-live-background/exe",root,files=new[]{"CodexLiveBackground.exe","startup\\DreamSkinPortHook.exe","manifest.json",".codex-background-install.json"}}));
  var keep=new Dictionary<string,string>();foreach(string relative in new[]{"wallpapers/personal.mp4","source/assets/pets/personal/pet.json","engine/runtime/ffmpeg/ffmpeg.exe"}){string path=Path.Combine(root,relative);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,"preserve "+relative);keep[path]=SoftwareUpdate.Hash(path);}foreach(string name in new[]{"pet-settings.json","wallpaper-library.json"}){string path=Path.Combine(state,name);File.WriteAllText(path,"preserve "+name);keep[path]=SoftwareUpdate.Hash(path);}
  var resources=Assembly.LoadFrom(Path.Combine(package,"CodexHubUpdater.exe"));Need(GuardComponents.Required(root),"Old installation does not request component migration");bool resumed=false;using(var process=Process.Start(new ProcessStartInfo(guard){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){Need(Until(()=>File.Exists(Path.Combine(root,@"startup\fixture-starts.txt"))),"Owned old guard did not start");GuardComponents.Install(root,state,resources,()=>{resumed=true;},false);Need(process.HasExited&&resumed,"Migration did not stop and request restoration of its own guard");}
  Need(FileVersionInfo.GetVersionInfo(guard).FileVersion=="1.7.0.9","Embedded guard program version was not restored");Need(!GuardComponents.Required(root),"Component migration repeats on every launch");foreach(var item in keep)Need(SoftwareUpdate.Hash(item.Key)==item.Value,"Component migration changed material/settings/runtime: "+item.Key);var index=json.Deserialize<SoftwareManifest>(File.ReadAllText(manifest));Need(index.files.Any(item=>item.path.Replace('\\','/')=="startup/DreamSkinPortHook.exe"&&item.sha256.Equals(SoftwareUpdate.Hash(guard),StringComparison.OrdinalIgnoreCase)),"Migration inventory has a stale guard hash");var marker=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,".codex-background-install.json")));Need(((System.Collections.IEnumerable)marker["files"]).Cast<object>().Select(Convert.ToString).Contains("historical-install-files.json"),"Migrated metadata is absent from uninstall ownership");
  string portable=Path.Combine(root,"portable");Directory.CreateDirectory(portable);File.Copy(manager,Path.Combine(portable,"CodexLiveBackground.exe"));File.WriteAllText(Path.Combine(portable,"manifest.json"),"{\"version\":\"1.7.0.9\",\"files\":[]}");File.WriteAllText(Path.Combine(portable,"cloud-pets.json"),"old program metadata");string old=SoftwareUpdate.Hash(Path.Combine(portable,"cloud-pets.json")),oldManifest=SoftwareUpdate.Hash(Path.Combine(portable,"manifest.json"));bool failed=false;try{GuardComponents.Install(portable,state,resources,null,false,count=>{if(count==2)throw new IOException("fixture interruption");});}catch(IOException){failed=true;}Need(failed&&SoftwareUpdate.Hash(Path.Combine(portable,"cloud-pets.json"))==old&&SoftwareUpdate.Hash(Path.Combine(portable,"manifest.json"))==oldManifest,"Interrupted component update did not roll back");Need(!File.Exists(Path.Combine(portable,"historical-install-files.json"))&&!Directory.Exists(Path.Combine(portable,"startup")),"Portable metadata migration installed a service");
  File.WriteAllText(Path.Combine(root,"service-compatibility.json"),File.ReadAllText(Path.Combine(package,"service-compatibility.json")).Replace(SoftwareUpdate.Hash(guard).ToUpperInvariant(),new string('0',64)).Replace(SoftwareUpdate.Hash(guard).ToLowerInvariant(),new string('0',64)));string before=SoftwareUpdate.Hash(manifest);failed=false;try{GuardComponents.Install(root,state,resources,null,false);}catch(InvalidDataException){failed=true;}Need(failed&&SoftwareUpdate.Hash(manifest)==before,"Unverified component hash changed the installation");
  File.WriteAllText(report,json.Serialize(new{pass=true,checks,embeddedResourcesVerified=true,oldGuardMigrated=true,doesNotRepeat=true,preservedFiles=keep.Count,failureRollback=true,unknownHashRejected=true,realCodexManipulated=false,realRegistrationChanged=false}));return 0;
 }catch(Exception error){File.WriteAllText(report,json.Serialize(new{pass=false,checks,error=error.ToString()}));return 1;}}
}
